function intervalSeconds(s){const m=s.trim().match(/^(?:(\d+):)?(\d{1,2})$/);return m?(+(m[1]||0)*60 + +m[2]):0}
function repEstimateSeconds(rep,pool='25'){const repeats=+rep.count||0,distance=+rep.distance||0,interval=intervalSeconds(rep.interval||''),transition=intervalSeconds(rep.transition||'2:00');return transition+repeats*(interval||distance*(pool==='25'?.9:1.05))}
function blockTotals(block,parentRepeat=1,pool='25'){let distance=0,seconds=0;const repeat=parentRepeat*(+block.repeat||1);blockItems(block).forEach(item=>{if(isRepItem(item)){distance+=repeat*(+item.count||0)*(+item.distance||0);seconds+=repeat*repEstimateSeconds(item,pool)}else{const totals=blockTotals(item,repeat,pool);distance+=totals.distance;seconds+=totals.seconds}});return{distance,seconds}}
function setTotals(set){return(set.blocks||[]).reduce((totals,block)=>{const next=blockTotals(block,1,set.pool||'25');return{distance:totals.distance+next.distance,seconds:totals.seconds+next.seconds}},{distance:0,seconds:0})}
function formatEstimate(seconds){return seconds?`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`:'—'}
function formatClock(seconds){const value=Math.max(0,Number(seconds)||0);return`${Math.floor(value/60)}:${String(value%60).padStart(2,'0')}`}
function updateRepStartTimes(pool){const unit=pool==='25'?'yd':'m',updateBlock=(block,start,showStarts=true)=>{if(showStarts)$('.block-start',block).textContent=`Start: ${formatClock(start)}`;let cursor=start;const repeat=Math.max(1,+val(block,'block-repeat')||1);for(let round=0;round<repeat;round++){const showThisRound=showStarts&&round===0;[...$('.block-items',block).children].forEach(item=>{if(item.classList.contains('rep')){const count=+val(item,'count')||0,distance=+val(item,'distance')||0,seconds=repEstimateSeconds({count,distance,transition:val(item,'transition'),interval:val(item,'interval')},pool);if(showThisRound)$('.rep-time',item).textContent=`Start: ${formatClock(cursor)} · Total: ${(count*distance).toLocaleString()} ${unit} · Est. ${formatEstimate(seconds)}`;cursor+=seconds}else cursor=updateBlock(item,cursor,showThisRound)})}return cursor};let cursor=0;[...blocks.children].forEach(block=>{cursor=updateBlock(block,cursor)})}
