function seedDrillsLibrary(){const drills=allDrills(),known=new Set(drills.map(drill=>`${drill.stroke}|${drill.name}`));let added=false;starterDrills.forEach(drill=>{if(!known.has(`${drill.stroke}|${drill.name}`)){drills.push({id:`drill_${Date.now().toString(36)}${Math.random().toString(36).slice(2,7)}`,...drill});added=true}});if(added||!localStorage.getItem(drillLibrarySeedKey))localStorage.setItem(drillLibraryKey,JSON.stringify(drills));localStorage.setItem(drillLibrarySeedKey,'true')}
