function logSyncSettings(){try{const own=JSON.parse(localStorage.getItem(logSyncKey)||'{}'),library=syncSettings();return{repository:library.repository||own.repository||'',branch:library.branch||own.branch||'main',file:'ll_log.json',token:library.token||own.token||'',lastSyncedSha:own.lastSyncedSha||''}}catch{return {file:'ll_log.json',branch:'main'}}}
