function scheduleSyncSettings(){try{const own=JSON.parse(localStorage.getItem(scheduleSyncKey)||'{}'),library=syncSettings(),log=logSyncSettings();return{repository:library.repository||own.repository||log.repository||'',branch:library.branch||own.branch||log.branch||'main',file:'ll_schedule.json',token:library.token||own.token||log.token||'',lastSyncedSha:own.lastSyncedSha||''}}catch{return {file:'ll_schedule.json',branch:'main'}}}
