function repositoryDetails(value){const input=String(value||'').trim().replace(/\/$/,'').replace(/\.git$/i,'');let slug=input;if(/^https?:\/\//i.test(input)){try{const url=new URL(input);if(url.hostname.toLowerCase()!=='github.com')return null;slug=url.pathname.replace(/^\/+|\/+$/g,'')}catch{return null}}if(!/^[a-z0-9_.-]+\/[a-z0-9_.-]+$/i.test(slug))return null;return{slug,url:`https://github.com/${slug.split('/').map(encodeURIComponent).join('/')}`}}
function updateRepositoryLink(){const details=repositoryDetails($('#github-repository').value),button=$('#open-user-repository');if(!button)return;button.disabled=!details;button.dataset.url=details?.url||''}
function openSyncSettings(){const settings=syncSettings(),details=repositoryDetails(settings.repository);$('#github-repository').value=details?.url||settings.repository||'';$('#github-branch').value=settings.branch||'main';$('#github-token').value=settings.token||'';githubConnectionStatus('');updateRepositoryLink();updateFolderSettings();$('#sync-dialog').showModal()}
function openLogSyncSettings(){const settings=logSyncSettings();$('#log-github-repository').value=settings.repository||'';$('#log-github-branch').value=settings.branch||'main';$('#log-github-file').value='ll_log.json';$('#log-github-token').value=settings.token||'';$('#log-sync-dialog').showModal()}
function githubApi(settings){const repository=repositoryDetails(settings.repository)?.slug||settings.repository;return `https://api.github.com/repos/${repository}/contents/${settings.file.split('/').map(encodeURIComponent).join('/')}`}
function githubHeaders(settings){return {'Accept':'application/vnd.github+json','X-GitHub-Api-Version':'2026-03-10',...(settings.token?{'Authorization':`Bearer ${settings.token}`}:{})}}
async function testGitHubConnection(){const button=$('#test-github-connection'),details=repositoryDetails($('#github-repository').value),branch=$('#github-branch').value.trim()||'main',token=$('#github-token').value.trim();if(!details||!token){const message='Enter a valid GitHub repository URL and personal access token first.';githubConnectionStatus(message,'error');toast(message);return}button.disabled=true;button.textContent='Testing…';githubConnectionStatus('Testing GitHub connection…','testing');try{const response=await fetch(`https://api.github.com/repos/${details.slug}/branches/${encodeURIComponent(branch)}`,{headers:githubHeaders({token}),cache:'no-store'});if(!response.ok){if(response.status===401)throw new Error('GitHub rejected this token.');if(response.status===403)throw new Error('This token does not have access to that repository.');if(response.status===404)throw new Error('Repository or branch was not found.');throw new Error(`GitHub returned ${response.status}.`)}const message=`✓ Connected to ${details.slug} (${branch}).`;githubConnectionStatus(message,'success');toast(message)}catch(error){const message=error.message||'Could not connect to GitHub.';githubConnectionStatus(message,'error');toast(message)}finally{button.disabled=false;button.textContent='Test connection'}}
function githubFileRequest(settings){return fetch(`${githubApi(settings)}?ref=${encodeURIComponent(settings.branch||'main')}&_=${Date.now()}`,{headers:githubHeaders(settings),cache:'no-store'})}async function githubError(response){const detail=await response.json().catch(()=>null);return detail?.message?`GitHub returned ${response.status}: ${detail.message}`:`GitHub returned ${response.status}.`}
function decodeBase64(value){return new TextDecoder().decode(Uint8Array.from(atob(value.replace(/\n/g,'')),char=>char.charCodeAt(0)))}
function encodeBase64(value){return btoa(String.fromCharCode(...new TextEncoder().encode(value)))}
function mergeSchedules(local,remote){const combined=new Map;[...remote,...local].forEach(entry=>combined.set(entry.id||`${entry.date}|${entry.set?.title}`,entry));return [...combined.values()].sort((a,b)=>String(a.date).localeCompare(String(b.date)))}
function rememberScheduleSyncedSha(settings,sha){saveScheduleSyncSettings({...settings,lastSyncedSha:sha});markSyncComplete('schedule')}
async function pushSchedule(retry=0){const settings=scheduleSyncSettings();if(!settings.repository||!settings.token)return;let scheduled=allScheduled();try{const check=await githubFileRequest(settings);if(!check.ok&&check.status!==404)throw new Error(`GitHub returned ${check.status}.`);const existing=check.ok?await check.json():null;if(existing&&settings.lastSyncedSha!==existing.sha){const payload=JSON.parse(decodeBase64(existing.content)),remote=Array.isArray(payload)?payload:payload.scheduledWorkouts;if(Array.isArray(remote)){scheduled=mergeSchedules(scheduled,remote);localStorage.setItem(calendarKey,JSON.stringify(scheduled))}}const content=JSON.stringify({version:1,updatedAt:new Date().toISOString(),scheduledWorkouts:scheduled},null,2),response=await fetch(githubApi(settings),{method:'PUT',headers:{...githubHeaders(settings),'Content-Type':'application/json'},body:JSON.stringify({message:'Sync swim workout schedule',content:encodeBase64(content),branch:settings.branch||'main',...(existing?{sha:existing.sha}:{})})});if(!response.ok){if(response.status===409&&retry===0)return pushSchedule(1);throw new Error(`GitHub returned ${response.status}.`)}const result=await response.json();rememberScheduleSyncedSha(settings,result.content?.sha||existing?.sha||'')}catch(error){console.warn('Could not automatically save the workout schedule.',error)}}
function queueLibraryAutoSave(){markSyncPending('library');queueFolderSave('library')}
function queueBlocksAutoSave(){markSyncPending('blocks');queueFolderSave('blocks')}
function queueDrillsAutoSave(){markSyncPending('drills');queueFolderSave('drills')}
function queueLogAutoSave(){markSyncPending('log');queueFolderSave('log')}
function queueScheduleAutoSave(){markSyncPending('schedule');queueFolderSave('schedule')}
function mergeLibraries(local,remote){const combined=new Map;[...remote,...local].forEach(set=>{const existing=combined.get(set.title);if(!existing||(+set.savedAt||0)>=(+existing.savedAt||0))combined.set(set.title,set)});return [...combined.values()].sort((a,b)=>(+b.savedAt||0)-(+a.savedAt||0))}
function mergeBlocksLibraries(local,remote){const combined=new Map;[...remote,...local].forEach(block=>combined.set(block.id||block.name,block));return [...combined.values()].sort((a,b)=>(+b.savedAt||0)-(+a.savedAt||0))}
async function pushBlocksLibrary(retry=0){const settings=blocksLibrarySyncSettings();if(!settings.repository||!settings.token)return;let saved=allSavedBlocks();try{const check=await githubFileRequest(settings);if(!check.ok&&check.status!==404)throw new Error(await githubError(check));const existing=check.ok?await check.json():null;if(existing&&settings.lastSyncedSha!==existing.sha){const payload=JSON.parse(decodeBase64(existing.content)),remote=Array.isArray(payload)?payload:payload.blocks;if(Array.isArray(remote)){saved=mergeBlocksLibraries(saved,remote);localStorage.setItem(blockLibraryKey,JSON.stringify(saved))}}const content=JSON.stringify({version:1,updatedAt:new Date().toISOString(),blocks:saved},null,2),response=await fetch(githubApi(settings),{method:'PUT',headers:{...githubHeaders(settings),'Content-Type':'application/json'},body:JSON.stringify({message:'Sync swim blocks library',content:encodeBase64(content),branch:settings.branch||'main',...(existing?{sha:existing.sha}:{})})});if(!response.ok){if(response.status===409&&retry===0)return pushBlocksLibrary(1);throw new Error(await githubError(response))}const result=await response.json();delete lastGitHubPushErrors.blocks;rememberBlocksSyncedSha(settings,result.content?.sha||existing?.sha||'')}catch(error){lastGitHubPushErrors.blocks=error.message||'Could not save the Blocks Library.';console.warn('Could not automatically save the Blocks Library.',error)}}
async function pushDrillsLibrary(retry=0){const settings=drillsLibrarySyncSettings();if(!settings.repository||!settings.token)return;let drills=allDrills();updateSyncStatus('syncing');try{const check=await githubFileRequest(settings);if(!check.ok&&check.status!==404)throw new Error(`GitHub returned ${check.status}.`);const existing=check.ok?await check.json():null;if(existing&&settings.lastSyncedSha!==existing.sha){const payload=JSON.parse(decodeBase64(existing.content)),remote=Array.isArray(payload)?payload:payload.drills;if(Array.isArray(remote)){const combined=new Map([...remote,...drills].map(drill=>[drill.id||`${drill.stroke}|${drill.name}`,drill]));drills=[...combined.values()];localStorage.setItem(drillLibraryKey,JSON.stringify(drills))}}const content=JSON.stringify({version:1,updatedAt:new Date().toISOString(),drills},null,2),response=await fetch(githubApi(settings),{method:'PUT',headers:{...githubHeaders(settings),'Content-Type':'application/json'},body:JSON.stringify({message:'Sync swim drills library',content:encodeBase64(content),branch:settings.branch||'main',...(existing?{sha:existing.sha}:{})})});if(!response.ok){if(response.status===409&&retry===0)return pushDrillsLibrary(1);throw new Error(`GitHub returned ${response.status}.`)}const result=await response.json();rememberDrillsSyncedSha(settings,result.content?.sha||existing?.sha||'');markSyncComplete('drills')}catch(error){console.warn('Could not automatically save the Drill Library.',error);updateSyncStatus(navigator.onLine?'review':'waiting')}}
let pendingConflict;
function rememberSyncedSha(settings,sha){saveSyncSettings({...settings,lastSyncedSha:sha});markSyncComplete('library')}
async function pullLibrary(){const settings=librarySyncSettings();if(!settings.repository){openSyncSettings();return}try{const response=await githubFileRequest(settings);if(!response.ok)throw new Error(response.status===404?'The JSON file was not found yet. Save your library first.':`GitHub returned ${response.status}.`);const file=await response.json(),payload=JSON.parse(decodeBase64(file.content)),remote=Array.isArray(payload)?payload:payload.sets;if(!Array.isArray(remote))throw new Error('That file does not contain a workout library.');localStorage.setItem(key,JSON.stringify(remote));renameWarmDownBlocks();ensureSetIds();rememberSyncedSha(settings,file.sha);renderLibrary();toast('Workout Library loaded from GitHub.')}catch(error){toast(error.message||'Could not load the GitHub Workout Library.')}}
async function showLatestConflict(settings){const response=await githubFileRequest(settings);if(!response.ok)return false;pendingConflict={settings,file:await response.json()};$('#sync-conflict-dialog').showModal();return true}
async function pushLibrary(force=false,retry=0){const settings=librarySyncSettings();if(!settings.repository||!settings.token){openSyncSettings();return}const content=JSON.stringify({version:1,updatedAt:new Date().toISOString(),sets:allSaved()},null,2);try{const endpoint=githubApi(settings),check=await githubFileRequest(settings);if(!check.ok&&check.status!==404)throw new Error(await githubError(check));const existing=check.ok?await check.json():null;if(existing&&!force&&settings.lastSyncedSha!==existing.sha){pendingConflict={settings,file:existing};$('#sync-conflict-dialog').showModal();return}const response=await fetch(endpoint,{method:'PUT',headers:{...githubHeaders(settings),'Content-Type':'application/json'},body:JSON.stringify({message:'Sync swim workout library',content:encodeBase64(content),branch:settings.branch||'main',...(existing?{sha:existing.sha}:{})})});if(!response.ok){if(response.status===409&&force&&retry===0)return pushLibrary(true,1);if(response.status===409&&!force&&await showLatestConflict(settings))return;throw new Error(await githubError(response))}const result=await response.json();delete lastGitHubPushErrors.library;rememberSyncedSha(settings,result.content?.sha||existing?.sha||'');toast('Workout Library saved to GitHub.')}catch(error){lastGitHubPushErrors.library=error.message||'Could not save the Workout Library.';toast(error.message||'Could not save the GitHub Workout Library.')}}
async function mergeThenPush(){if(!pendingConflict)return;const {settings,file}=pendingConflict;try{const payload=JSON.parse(decodeBase64(file.content)),remote=Array.isArray(payload)?payload:payload.sets;if(!Array.isArray(remote))throw new Error('That file does not contain a workout library.');localStorage.setItem(key,JSON.stringify(mergeLibraries(allSaved(),remote)));rememberSyncedSha(settings,file.sha);renderLibrary();$('#sync-conflict-dialog').close();pendingConflict=undefined;await pushLibrary(true);if(!isSyncPending('library'))await flushSyncOutbox()}catch(error){toast(error.message||'Could not merge the GitHub library.')}}
let pendingLogConflict;
function rememberLogSyncedSha(settings,sha){saveLogSyncSettings({...settings,lastSyncedSha:sha});markSyncComplete('log')}
function mergeLogs(local,remote){const combined=new Map;[...remote,...local].forEach(log=>combined.set(`${log.title}|${log.date}`,log));return [...combined.values()].sort((a,b)=>String(b.date).localeCompare(String(a.date)))}
async function pullLog(){const settings=logSyncSettings();if(!settings.repository||!settings.token){openLogSyncSettings();return}try{const response=await githubFileRequest(settings);if(!response.ok)throw new Error(response.status===404?'The log JSON file was not found yet. Save your log first.':`GitHub returned ${response.status}.`);const file=await response.json(),payload=JSON.parse(decodeBase64(file.content)),remote=Array.isArray(payload)?payload:payload.logs;if(!Array.isArray(remote))throw new Error('That file does not contain a workout log.');localStorage.setItem(logKey,JSON.stringify(remote));renameWarmDownBlocks();ensureSetIds();rememberLogSyncedSha(settings,file.sha);renderLog();toast('Workout log loaded from GitHub.')}catch(error){toast(error.message||'Could not load the GitHub workout log.')}}
async function syncGitHubFilesOnStartup(discardLocal=false){const sources=[{settings:librarySyncSettings(),property:'sets',storageKey:key,remember:rememberSyncedSha,label:'Workout Library'},{settings:blocksLibrarySyncSettings(),property:'blocks',storageKey:blockLibraryKey,remember:rememberBlocksSyncedSha,label:'Blocks Library'},{settings:logSyncSettings(),property:'logs',storageKey:logKey,remember:rememberLogSyncedSha,label:'Workout Log'},{settings:scheduleSyncSettings(),property:'scheduledWorkouts',storageKey:calendarKey,remember:rememberScheduleSyncedSha,label:'Schedule'}].filter(source=>source.settings.repository&&source.settings.token);if(!sources.length){if(discardLocal)toast('Save your GitHub Settings first.');return}let completed=0;await Promise.all(sources.map(async source=>{try{const response=await githubFileRequest(source.settings);if(!response.ok){console.warn(`Could not load ${source.label} from GitHub: ${response.status}.`);return}const file=await response.json(),payload=JSON.parse(decodeBase64(file.content)),remote=Array.isArray(payload)?payload:payload[source.property];if(!Array.isArray(remote))throw new Error('Invalid JSON structure.');localStorage.setItem(source.storageKey,JSON.stringify(remote));source.remember(source.settings,file.sha);completed++}catch(error){console.warn(`Could not load ${source.label} from GitHub.`,error)}}));if(!completed){if(discardLocal)toast('Could not pull any GitHub workout files.');return}renameWarmDownBlocks();renameWarmUpBlocks();ensureSetIds();renderLibrary();renderBlocksLibrary();renderLog();renderCalendar();renderSchedule();if(discardLocal||!hasUnsavedChanges){hasUnsavedChanges=false;if(!loadTodayScheduledWorkout())loadSet(defaultSet());updateTotals()}toast(`Pulled ${completed} GitHub file${completed===1?'':'s'} without saving or merging local changes.`)}
const pullGitHubFilesUnsafe=syncGitHubFilesOnStartup;
async function flushSyncOutbox(){if(!navigator.onLine){updateSyncStatus('waiting');return}const pending=syncOutbox(),jobs=[],ready=settings=>settings.repository&&settings.token;updateSyncStatus('syncing');if(pending.library&&ready(librarySyncSettings()))jobs.push(pushLibrary());if(pending.blocks&&ready(blocksLibrarySyncSettings()))jobs.push(pushBlocksLibrary());if(pending.drills&&ready(drillsLibrarySyncSettings()))jobs.push(pushDrillsLibrary());if(pending.log&&ready(logSyncSettings()))jobs.push(pushLog());if(pending.schedule&&ready(scheduleSyncSettings()))jobs.push(pushSchedule());await Promise.allSettled(jobs);updateSyncStatus(Object.values(syncOutbox()).some(Boolean)?'review':'synced')}
async function pushAllGitHub(){const settings=syncSettings();if(!settings.repository||!settings.token){openSyncSettings();githubConnectionStatus('Save your GitHub settings before pushing.','error');return}const pendingTypes=Object.entries(syncOutbox()).filter(([,pending])=>pending).map(([type])=>type);if(!pendingTypes.length){const message='No local changes are waiting to push.';githubConnectionStatus(message);toast(message);return}lastGitHubPushErrors={};githubConnectionStatus(`Pushing ${pendingTypes.join(', ')}…`,'testing');await flushSyncOutbox();const remaining=Object.entries(syncOutbox()).filter(([,pending])=>pending).map(([type])=>type),details=remaining.map(type=>lastGitHubPushErrors[type]).filter(Boolean);const message=remaining.length?(details.length?details.join(' '):`Push needs attention for: ${remaining.join(', ')}.`):'✓ Your local changes were pushed to GitHub.';githubConnectionStatus(message,remaining.length?'error':'success');toast(message)}
async function pullDrillsFromGitHub(){const settings=drillsLibrarySyncSettings();if(!settings.repository||!settings.token)return;try{const response=await githubFileRequest(settings);if(!response.ok)return;const file=await response.json(),payload=JSON.parse(decodeBase64(file.content)),remote=Array.isArray(payload)?payload:payload.drills;if(!Array.isArray(remote))return;localStorage.setItem(drillLibraryKey,JSON.stringify(remote));rememberDrillsSyncedSha(settings,file.sha);renderDrillsLibrary()}catch(error){console.warn('Could not load the Drill Library from GitHub.',error)}}
syncGitHubFilesOnStartup=async function(discardLocal=false){if(!discardLocal)return;await Promise.all([pullGitHubFilesUnsafe(true),pullDrillsFromGitHub()]);if(dataStorePath)await writeFolderFiles(Object.keys(folderFiles))};
window.addEventListener('online',()=>updateSyncStatus(Object.values(syncOutbox()).some(Boolean)?'waiting':'local'));window.addEventListener('offline',()=>updateSyncStatus('waiting'));
async function showLatestLogConflict(settings){const response=await githubFileRequest(settings);if(!response.ok)return false;pendingLogConflict={settings,file:await response.json()};$('#log-sync-conflict-dialog').showModal();return true}
async function pushLog(force=false,retry=0){const settings=logSyncSettings();if(!settings.repository||!settings.token){openLogSyncSettings();return}const content=JSON.stringify({version:1,updatedAt:new Date().toISOString(),logs:allLogs()},null,2);try{const endpoint=githubApi(settings),check=await githubFileRequest(settings);if(!check.ok&&check.status!==404)throw new Error(`GitHub returned ${check.status}.`);const existing=check.ok?await check.json():null;if(existing&&!force&&settings.lastSyncedSha!==existing.sha){pendingLogConflict={settings,file:existing};$('#log-sync-conflict-dialog').showModal();return}const response=await fetch(endpoint,{method:'PUT',headers:{...githubHeaders(settings),'Content-Type':'application/json'},body:JSON.stringify({message:'Sync swim workout log',content:encodeBase64(content),branch:settings.branch||'main',...(existing?{sha:existing.sha}:{})})});if(!response.ok){if(response.status===409&&force&&retry===0)return pushLog(true,1);if(response.status===409&&!force&&await showLatestLogConflict(settings))return;const detail=await response.json().catch(()=>null);throw new Error(detail?.message||'GitHub changed the workout log again while saving. Please try once more.')}const result=await response.json();rememberLogSyncedSha(settings,result.content?.sha||existing?.sha||'');toast('Workout log saved to GitHub.')}catch(error){toast(error.message||'Could not save the GitHub workout log.')}}
async function mergeLogThenPush(){if(!pendingLogConflict)return;const {settings,file}=pendingLogConflict;try{const payload=JSON.parse(decodeBase64(file.content)),remote=Array.isArray(payload)?payload:payload.logs;if(!Array.isArray(remote))throw new Error('That file does not contain a workout log.');localStorage.setItem(logKey,JSON.stringify(mergeLogs(allLogs(),remote)));rememberLogSyncedSha(settings,file.sha);renderLog();$('#log-sync-conflict-dialog').close();pendingLogConflict=undefined;await pushLog(true);if(!isSyncPending('log'))await flushSyncOutbox()}catch(error){toast(error.message||'Could not merge the GitHub workout log.')}}
function removeLegacySamples(){if(localStorage.getItem(sampleCleanupKey))return;const titles=new Set(['Sprint & Turns','IM Precision','Distance Ladder','Meet Prep']);localStorage.setItem(key,JSON.stringify(allSaved().filter(set=>!titles.has(set.title))));localStorage.setItem(logKey,JSON.stringify(allLogs().filter(log=>!titles.has(log.title))));localStorage.setItem(sampleCleanupKey,'true')}
function seedRequestedWorkouts(){if(localStorage.getItem(requestedWorkoutSeedKey))return;const saved=allSaved(),savedTitles=new Set(saved.map(set=>set.title)),logs=allLogs(),loggedTitles=new Set(logs.map(log=>`${log.title}|${log.date}`));localStorage.setItem(key,JSON.stringify([...requestedLibrary.filter(set=>!savedTitles.has(set.title)),...saved]));localStorage.setItem(logKey,JSON.stringify([...requestedLogs.filter(log=>!loggedTitles.has(`${log.title}|${log.date}`)),...logs]));localStorage.setItem(requestedWorkoutSeedKey,'true')}
function seedJulyCalendarWorkouts(){if(localStorage.getItem(julyCalendarSeedKey))return;const scheduled=allScheduled(),additions=[{id:'calendar_july_28_2026',date:'2026-07-28',notes:'Build aerobic rhythm and finish with strong, controlled 100s.',set:{title:'July Endurance Builder',focus:'Aerobic endurance and pacing',tags:'freestyle, aerobic',pool:'25',blocks:[{name:'Warm Up',note:'Swim, kick, and drill with a strong body line.',reps:[{count:1,distance:500,stroke:'Choice',interval:'',detail:'100 swim / 100 kick / 100 drill / 200 swim'}]},{name:'Main Set',note:'Hold a controlled threshold effort.',reps:[{count:4,distance:200,stroke:'Freestyle',interval:'2:55',detail:'negative split each 200'},{count:4,distance:100,stroke:'Freestyle',interval:'1:25',detail:'descend 1–4'}]},{name:'Cool Down',note:'Easy choice.',reps:[{count:1,distance:300,stroke:'Choice',interval:'',detail:''}]}]}},{id:'calendar_july_30_2026',date:'2026-07-30',notes:'Prioritize clean IM transitions, turns, and underwater speed.',set:{title:'July IM Turns & Skills',focus:'IM transitions, turns, and stroke technique',tags:'IM, turns, technique',pool:'25',blocks:[{name:'Warm Up',note:'Prepare each stroke and reinforce clean walls.',reps:[{count:1,distance:400,stroke:'Choice',interval:'',detail:'swim / drill / kick'}]},{name:'IM Skills',note:'Stay precise through every transition.',reps:[{count:4,distance:100,stroke:'IM',interval:'1:50',detail:'25 drill / 75 swim'},{count:8,distance:50,stroke:'Choice',interval:'1:05',detail:'fast into turn, easy out'}]},{name:'Cool Down',note:'Easy choice.',reps:[{count:1,distance:300,stroke:'Choice',interval:'',detail:''}]}]}}],known=new Set(scheduled.map(entry=>`${entry.date}|${entry.set?.title}`));localStorage.setItem(calendarKey,JSON.stringify([...scheduled,...additions.filter(entry=>!known.has(`${entry.date}|${entry.set.title}`))]));localStorage.setItem(julyCalendarSeedKey,'true')}
function seedFirstDayWorkout(){if(localStorage.getItem(firstDayWorkoutSeedKey))return;const saved=allSaved();if(!saved.some(set=>set.title==='First Day')){saved.unshift({id:newSetId(),title:'First Day',focus:'Evaluation',tags:'Evaluation',pool:'25',savedAt:Date.now(),blocks:[{name:'Warm Up',note:'',reps:[{count:1,distance:200,stroke:'Choice',interval:'5:00',detail:''},{count:1,distance:200,stroke:'Kick',interval:'5:00',detail:''},{count:4,distance:50,stroke:'Choice',interval:'1:00',detail:'25 scull / 25 swim'}]},{name:'Main Set',note:'',reps:[]},{name:'Cool Down',note:'',reps:[]}]});localStorage.setItem(key,JSON.stringify(saved))}localStorage.setItem(firstDayWorkoutSeedKey,'true')}
function fixPaceLadderInterval(){if(localStorage.getItem(paceLadderIntervalFixKey))return;const fix=entries=>entries.map(entry=>{const set=entry.set||entry;if(set.title!=='Freestyle Pace Ladder'||set.blocks?.[0]?.name!=='Warm-up')return entry;const next=JSON.parse(JSON.stringify(entry)),target=next.set||next;target.blocks[0].reps[0].interval='1:30';return next});localStorage.setItem(key,JSON.stringify(fix(allSaved())));localStorage.setItem(logKey,JSON.stringify(fix(allLogs())));localStorage.setItem(paceLadderIntervalFixKey,'true')}
function tagList(tags){return String(tags||'').split(',').map(t=>t.trim()).filter(Boolean)}
function duplicateTitle(title,saved){let number=1,candidate=`${title} Copy`;const names=new Set(saved.map(set=>set.title));while(names.has(candidate)){number++;candidate=`${title} Copy ${number}`}return candidate}
