function renderDeck(){const set=currentSet(),totals=setTotals(set),unit=set.pool==='25'?'yd':'m',time=totals.seconds?`${Math.floor(totals.seconds/60)} min ${totals.seconds%60} sec`:'—';$('#deck-sheet').innerHTML=`<p class="deck-kicker">HIGH SCHOOL SWIM · DECK SHEET</p><h1 class="deck-title">${escapeHtml(set.title)}</h1><div class="deck-meta"><span><strong>Focus</strong><br>${escapeHtml(set.focus||'—')}</span><span><strong>Pool</strong><br>${set.pool} ${unit} pool</span><span><strong>Total</strong><br>${totals.distance.toLocaleString()} ${unit}</span><span><strong>Interval time</strong><br>${time}</span></div>${set.blocks.map(block=>`<section class="deck-block"><h2>${escapeHtml(block.name)}</h2>${block.note?`<p class="deck-note">${escapeHtml(block.note)}</p>`:''}<table class="deck-table"><thead><tr><th>SET</th><th>STROKE</th><th>INTERVAL</th><th>DETAIL</th></tr></thead><tbody>${block.reps.map(r=>`<tr><td class="deck-setline">${r.count} × ${r.distance} ${unit}</td><td>${escapeHtml(r.stroke)}</td><td>${escapeHtml(r.interval||'—')}</td><td class="deck-detail">${escapeHtml(r.detail||'—')}</td></tr>`).join('')}</tbody></table></section>`).join('')}<footer class="deck-footer"><span>Lane Lines · ${new Date().toLocaleDateString()}</span><span>Good work. Swim with purpose.</span></footer>`}
