function renderDeck(){const set=currentSet(),totals=setTotals(set),unit=set.pool==='25'?'yd':'m',time=totals.seconds?`${Math.floor(totals.seconds/60)} min ${totals.seconds%60} sec`:'—',startTimes=setLineStartTimes(set),body=set.blocks.map(block=>deckBlock(block,unit,startTimes,set.pool||'25')).join('');$('#deck-sheet').innerHTML=`<p class="deck-kicker">HIGH SCHOOL SWIM · DECK SHEET</p><h1 class="deck-title">${escapeHtml(set.title)}</h1><div class="deck-meta"><span><strong>Focus</strong><br>${escapeHtml(set.focus||'—')}</span><span><strong>Pool</strong><br>${set.pool} ${unit} pool</span><span><strong>Total</strong><br>${totals.distance.toLocaleString()} ${unit}</span><span><strong>Interval time</strong><br>${time}</span></div>${body}<footer class="deck-footer"><span>Lane Lines · ${new Date().toLocaleDateString()}</span><span>Good work. Swim with purpose.</span></footer>`}
