function organizeBlocksByFocus(){const area=$('#saved-blocks'),cards=[...area.querySelectorAll('.saved-block')];if(!cards.length)return;const metadata=new Map(allSavedBlocks().map(entry=>[entry.name,blockLibraryMeta(entry)])),groups=new Map;cards.forEach(card=>{const name=$('strong',card)?.textContent||'',focus=metadata.get(name)?.focus?.trim()||'No focus';if(!groups.has(focus))groups.set(focus,[]);groups.get(focus).push(card)});area.innerHTML='';[...groups.keys()].sort((a,b)=>a==='No focus'?1:b==='No focus'?-1:a.localeCompare(b,undefined,{sensitivity:'base'})).forEach(focus=>{const group=document.createElement('section');group.className='blocks-focus-group';const heading=document.createElement('h2');heading.textContent=focus;const entries=document.createElement('div');entries.className='blocks-focus-entries';groups.get(focus).forEach(card=>entries.append(card));group.append(heading,entries);area.append(group)})}
function addBlockLibraryDuplicateActions(){document.querySelectorAll('#saved-blocks .saved-block').forEach(card=>{const actions=$('.set-actions',card);if(!actions||$('.duplicate-set',actions))return;const sourceName=$('strong',card)?.textContent||'',button=document.createElement('button');button.className='duplicate-set';button.type='button';button.textContent='Duplicate';button.title=`Duplicate ${sourceName}`;button.onclick=()=>{const saved=allSavedBlocks(),source=saved.find(entry=>entry.name===sourceName);if(!source)return;const copy=JSON.parse(JSON.stringify(source)),base=`${source.name} copy`;let name=base,suffix=2;while(saved.some(entry=>entry.name.toLocaleLowerCase()===name.toLocaleLowerCase()))name=`${base} ${suffix++}`;copy.id=`block_${Date.now().toString(36)}${Math.random().toString(36).slice(2,7)}`;copy.name=name;copy.savedAt=Date.now();saved.unshift(copy);localStorage.setItem(blockLibraryKey,JSON.stringify(saved));renderBlocksLibrary();queueBlocksAutoSave();toast(`Created ${name}.`)};actions.insertBefore(button,$('.trash',actions))})}
